def diff_releases(a: Release, b: Release) -> list[Change]:
    changes = []
    for fname in sorted(set(a.files) | set(b.files)):
        if fname not in b.files:
            changes.append(Change("file_missing", fname, [], {"missing_in": b.name}))
        elif fname not in a.files:
            changes.append(Change("file_added", fname, [], {"missing_in": a.name}))
        else:
            changes.extend(diff_file(a.files[fname], b.files[fname]))
    return changes + unlinked_changes(a, b) + coverage_changes(a, b)

def verdicts(runs: list[AnalysisRun], baseline_unverified: list[str]) -> dict[str, dict]:
    policy = Policy.load(TOWER_POLICY)
    out = {}
    for run in runs:
        results = [
            CheckResult("provenance", "ok", {"baseline_verified": not baseline_unverified,
                                             "unverified_files": baseline_unverified}),
            CheckResult("impact", "ok", _metrics(run)),
        ]
        ev = evaluate(results, policy, expected={"provenance", "impact"})
        out[run.analysis.id] = ev

def _load_rows(p: Path, fname: str, idcol: str) -> FileView:
    df = pd.read_csv(p, sep="\t", dtype=str, keep_default_na=False)
    if idcol not in df.columns:
        idcol = df.columns[0]
    df = df.set_index(idcol)
    df = df[~df.index.duplicated(keep="first")]
    v = FileView(fname, p, "rows", list(df.columns), list(df.index), _rows=df, idcol=idcol)
    for sid, row in zip(df.index, df.itertuples(index=False, name=None)):
        v.fingerprints[sid] = _fp(row)
        if all(x.strip() in MISSING for x in row):
            v.empty.add(sid)

def _load_matrix(p: Path, fname: str) -> FileView:
    with _open_text(p) as f:
        header = f.readline().rstrip("\n").split("\t")
        cols = header[1:]
        first = {}
        for i, c in enumerate(cols):
            first.setdefault(c, i)
        keep = sorted(first.values())
        hashers = [hashlib.sha256() for _ in keep]
        nonmissing = [False] * len(keep)
        features = []
        for line in f:
            parts = line.rstrip("\n").split("\t")
            features.append(parts[0])
            vals = parts[1:]
            for j, i in enumerate(keep):
                x = vals[i] if i < len(vals) else ""
                hashers[j].update((x + SEP).encode())
                if not nonmissing[j] and x.strip() not in MISSING:
                    nonmissing[j] = True
    samples = [cols[i] for i in keep]
    v = FileView(fname, p, "columns", features, samples)
    for j, s in enumerate(samples):
        v.fingerprints[s] = hashers[j].hexdigest()[:20]
        if not nonmissing[j]:
            v.empty.add(s)

